/**
 * migrate.ts — Drizzle Migrate runner with baseline support.
 *
 * Applies pending Drizzle-generated migrations from ./drizzle using the
 * official drizzle-orm migrator (which tracks applied migrations in the
 * `drizzle.__drizzle_migrations` table).
 *
 * Baseline behaviour
 * ------------------
 * The first migration (0000_baseline) was generated by `drizzle-kit generate`
 * from the schema that already existed in dev and production. On an existing
 * database that pre-dates this migration framework, running 0000_baseline
 * would fail with "relation already exists" errors. The same applies to any
 * subsequent migration that simply models tables which were already created
 * by the legacy raw-SQL migration step (`scripts/src/migrate.ts`). To handle
 * that transition:
 *
 *   - If the database already contains application tables (we look for
 *     `tenants`), every migration in the journal that is tagged at-or-before
 *     BASELINE_CUTOFF whose hash is not yet in `drizzle.__drizzle_migrations`
 *     is registered as "applied" without executing its SQL.
 *   - Any migration generated AFTER the baseline is always executed normally.
 *
 * Going forward developers should:
 *
 *   1. Edit `lib/db/src/schema/*.ts`
 *   2. Run `pnpm --filter @workspace/db run generate` to produce a new
 *      versioned `.sql` file under `lib/db/drizzle/`
 *   3. Commit both the schema change and the generated migration
 *
 * Migrations are then applied automatically:
 *   - Dev: by the post-merge hook (`scripts/post-merge.sh`)
 *   - Production: by the api-server deployment build step
 */
import path from "path";
import fs from "fs";
import crypto from "crypto";
import { fileURLToPath } from "url";
import pg from "pg";
import { drizzle } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const MIGRATIONS_FOLDER = path.resolve(__dirname, "../drizzle");

/**
 * Drizzle migration tag at-or-before which migrations should be baselined
 * (registered as applied without executing) when the tracker table is brand
 * new on an existing database. Update this only when introducing a new
 * baseline checkpoint that should be skipped on existing deployments.
 */
const BASELINE_CUTOFF = "0002_gigantic_banshee";

interface JournalEntry {
  idx: number;
  version: string;
  when: number;
  tag: string;
  breakpoints: boolean;
}

interface Journal {
  version: string;
  dialect: string;
  entries: JournalEntry[];
}

async function tableExists(
  client: pg.PoolClient,
  schema: string,
  name: string,
): Promise<boolean> {
  const { rows } = await client.query<{ exists: boolean }>(
    `SELECT EXISTS (
       SELECT 1 FROM information_schema.tables
       WHERE table_schema = $1 AND table_name = $2
     ) AS exists`,
    [schema, name],
  );
  return rows[0]?.exists ?? false;
}

function hashMigrationSql(sql: string): string {
  // Match drizzle-orm's readMigrationFiles: SHA256 of the raw .sql file body.
  return crypto.createHash("sha256").update(sql).digest("hex");
}

async function baselineIfNeeded(pool: pg.Pool): Promise<void> {
  if (!fs.existsSync(MIGRATIONS_FOLDER)) return;
  const journalPath = path.join(MIGRATIONS_FOLDER, "meta", "_journal.json");
  if (!fs.existsSync(journalPath)) return;

  const client = await pool.connect();
  try {
    const hasTenants = await tableExists(client, "public", "tenants");
    if (!hasTenants) {
      // Fresh database — let the migrator create everything from scratch.
      return;
    }

    await client.query(`CREATE SCHEMA IF NOT EXISTS drizzle`);
    await client.query(`
      CREATE TABLE IF NOT EXISTS drizzle.__drizzle_migrations (
        id   SERIAL PRIMARY KEY,
        hash text NOT NULL,
        created_at bigint
      )
    `);

    // Collect already-registered migration hashes so we don't double-insert.
    const { rows: existing } = await client.query<{ hash: string }>(
      `SELECT hash FROM drizzle.__drizzle_migrations`,
    );
    const existingHashes = new Set(existing.map((r) => r.hash));

    const journal: Journal = JSON.parse(fs.readFileSync(journalPath, "utf8"));
    const candidates = journal.entries
      .slice()
      .sort((a, b) => a.idx - b.idx)
      .filter((e) => e.tag <= BASELINE_CUTOFF);

    const toBaseline: { entry: JournalEntry; hash: string }[] = [];
    for (const entry of candidates) {
      const sqlPath = path.join(MIGRATIONS_FOLDER, `${entry.tag}.sql`);
      const sqlBody = fs.readFileSync(sqlPath, "utf8");
      const hash = hashMigrationSql(sqlBody);
      if (!existingHashes.has(hash)) {
        toBaseline.push({ entry, hash });
      }
    }

    if (toBaseline.length === 0) return;

    console.log(
      `migrate: existing database detected — baselining ` +
        `${toBaseline.length} migration(s) up to ${BASELINE_CUTOFF}.`,
    );

    await client.query("BEGIN");
    for (const { entry, hash } of toBaseline) {
      await client.query(
        `INSERT INTO drizzle.__drizzle_migrations (hash, created_at) VALUES ($1, $2)`,
        [hash, entry.when],
      );
      console.log(`  baseline ${entry.tag}`);
    }
    await client.query("COMMIT");
  } catch (err) {
    await client.query("ROLLBACK").catch(() => {});
    throw err;
  } finally {
    client.release();
  }
}

async function main() {
  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    throw new Error("DATABASE_URL environment variable is required");
  }

  const pool = new pg.Pool({ connectionString: databaseUrl });
  try {
    await baselineIfNeeded(pool);

    const db = drizzle(pool);
    await migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
    console.log("migrate: drizzle migrations up to date.");
  } finally {
    await pool.end();
  }
}

main().catch((err) => {
  console.error("migrate: failed", err);
  process.exit(1);
});
